#!/usr/bin/env node
/**
 * SD-LEARN-FIX-ADDRESS-PATTERN-LEARN-158 — Explore evidence at LEAD-TO-PLAN.
 *
 * A separate Explore sub-agent independently re-verified the LEAD-phase investigation that
 * corrected this SD's scope (originally 4 gate-fix items auto-generated by /learn from stale,
 * mis-timestamped issue_patterns; corrected to a timestamp-fidelity fix in the retro-pattern
 * extraction pipeline). This script records that independent verification as canonical evidence.
 */
import 'dotenv/config';
import { resolveSubAgentRepo, applySubAgentRepoVerdict } from '../../lib/sub-agents/resolve-repo.js';
import { storeSubAgentResults } from '../../lib/sub-agent-executor/results-storage.js';
import { createClient } from '@supabase/supabase-js';
import { isMainModule } from '../../lib/utils/is-main-module.js';

const SD_KEY = 'SD-LEARN-FIX-ADDRESS-PATTERN-LEARN-158';

async function main() {
  const supabase = createClient(process.env.SUPABASE_URL || process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY);

  const { data: sdRow, error: sdErr } = await supabase
    .from('strategic_directives_v2')
    .select('id')
    .eq('sd_key', SD_KEY)
    .single();
  if (sdErr) throw sdErr;

  const exploreResults = {
    verdict: 'PASS',
    confidence: 95,
    phase: 'LEAD',
    execution_time_ms: 0,
    summary: "CONFIRMED the SD's auto-generated premise was false and the corrected root cause is real, via independent re-derivation (not trusting the prior investigation's own claims). Traced and confirmed the full call chain end to end with exact line citations: .github/workflows/retro-pattern-extraction-cron.yml:15-16 (hourly cron, not disabled, added by QF-20260911-299/PR #8718) -> scripts/extract-pending-retro-patterns.mjs:25-30 (selects retrospectives WHERE learning_extracted_at IS NULL ORDER BY created_at ASC LIMIT 100, oldest-first; created_at is read only for an age-alarm metric, never threaded onward) -> scripts/auto-extract-patterns-from-retro.js:245 (kb.recordOccurrence({pattern_id, sd_id, ...}), no timestamp; grep of the whole file for 'created_at' returns zero matches) -> lib/learning/issue-knowledge-base.js:168,283-284 (recordOccurrence -> recordSiteAndMaybeEscalate(supabase, updated, {sd_id}), no timestamp) -> lib/learning/class-escalation.js:168,171 (recordSiteAndMaybeEscalate -> mergeSite(pattern.metadata, site, opts.now || new Date())) -> lib/learning/class-escalation.js:57,70 (mergeSite defaults now=new Date(), stamps first_seen: now.toISOString()). Searched repo-wide for every caller of recordOccurrence/recordSiteAndMaybeEscalate and confirmed NONE pass a historical timestamp: lib/rca/rca-orchestrator.js:319,382 is a legitimately real-time path (also defaults to now(), correctly); lib/team/findings-extractor.js:69 is dead code (no live caller beyond its own barrel re-export); scripts/archive/one-time/record-pattern-success.js:65 is archived/manual. Confirmed opts.now is entirely unwired/untested anywhere -- tests/unit/learning/class-escalation.test.js never exercises mergeSite's third argument.",
    critical_issues: [],
    warnings: [
      {
        id: 'EXP-1',
        severity: 'LOW',
        issue: 'kb.createPattern (a brand-new pattern\'s first occurrence) never calls recordSiteAndMaybeEscalate at all, and issue_patterns.created_at itself (DB-default now()) suffers the same wall-clock-vs-historical mismatch for newly-minted patterns. Same root defect class, different insert path -- correctly deferred out of this SD\'s scope per the PRD, but worth a one-line mention as a known adjacent gap.',
      },
    ],
    recommendations: [
      'Add an optional occurred_at (or similar) parameter threaded from extractPatternsFromRetrospective (retro.created_at) -> recordOccurrence -> recordSiteAndMaybeEscalate -> mergeSite\'s now, defaulting to new Date() everywhere it is omitted so the real-time RCA-orchestrator path is byte-identical to today.',
      'Regression test: a synthetic retro fixture with an old created_at, run through extractPatternsFromRetrospective, must produce a site whose first_seen equals the fixture\'s created_at, not Date.now() at test-run time.',
    ],
    detailed_analysis: {
      commands_run: [
        'Read scripts/extract-pending-retro-patterns.mjs, scripts/auto-extract-patterns-from-retro.js, lib/learning/issue-knowledge-base.js, lib/learning/class-escalation.js in full',
        'git log -1 --format=%H,%ai,%s -- .github/workflows/retro-pattern-extraction-cron.yml -> ea70e1a79da, 2026-09-12, confirms QF-20260911-299/PR #8718',
        'grep -c "created_at" scripts/auto-extract-patterns-from-retro.js -> 0',
        'Repo-wide grep for every caller of recordOccurrence and recordSiteAndMaybeEscalate',
        'DB spot-check: PAT-LES-15c6ed980a2e (41 occurrences, 21 sites, first_seen dates {2026-09-13,2026-09-14}), PAT-LES-752e6a374f67 (40 occurrences, 20 sites, all first_seen=2026-09-14), PAT-LES-e02af6e8e18d (19 sites, all first_seen=2026-09-14) -- all sites resolve to strategic_directives_v2 rows created+completed 2026-02-28',
        'Correlation check: retro 5d0dc0ea-8ce0-49dc-b0ad-735e84d19b9c learning_extracted_at=2026-09-14T12:08:17.558Z vs. PAT-LES-15c6ed980a2e site first_seen=2026-09-14T12:08:15.679Z for the same sd_id -- 2 seconds apart, same cron-extraction run',
        'Scale check: SELECT count(*) FROM retrospectives WHERE learning_extracted_at IS NULL -> 7,983 of 9,869 rows (81%), oldest pending created_at=2026-02-13 -- confirms this is an ongoing, actively-draining backlog, not a one-time artifact confined to the 4 named patterns',
        'Disconfirming-evidence check: verified the recorded sd_id in each site is the retro\'s ORIGINAL sd_id (the SD the retro was written about), not any SD active today; verified the site object shape {key, sd_id, first_seen} matches only the retro-extraction path (no gate/file/stage fields, which the real-time RCA-orchestrator path always includes) -- ruling out the alternative explanation that these are genuine fresh occurrences',
      ],
    },
    metadata: { independent_verification: true },
  };

  const resolution = await resolveSubAgentRepo({
    sdId: sdRow.id,
    targetApplication: 'EHG_Engineer',
    subAgentCode: 'EXPLORE',
    probeExistsRelative: 'scripts/one-off/learn-158-lead-to-plan-evidence.mjs',
    supabase,
  });
  applySubAgentRepoVerdict(exploreResults, resolution, { skipVerdictAdjust: false });
  const stored = await storeSubAgentResults('EXPLORE', sdRow.id, { code: 'EXPLORE', name: 'Explore' }, exploreResults, { sdKey: SD_KEY, phase: 'LEAD' });
  console.log('STORED:', 'EXPLORE', JSON.stringify({ id: stored?.id, verdict: stored?.verdict, phase: stored?.phase }));
}

if (isMainModule(import.meta.url)) {
  main().catch((err) => {
    console.error(err);
    process.exit(1);
  });
}
